window.ScripturaLexicons.BDAG_PART_0082 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-diadema-bdag\" data-source=\"BDAG\" data-search=\"διάδημα, ατος, τό diádēma substantivo neutro diadema; faixa régia; coroa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">διάδημα, ατος, τό</td><td>substantivo neutro</td><td>diadema; faixa régia; coroa</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-diadidomi-bdag\" data-source=\"BDAG\" data-search=\"διαδίδωμι diadídōmi verbo distribuir; repartir; dar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">διαδίδωμι</td><td>verbo</td><td>distribuir; repartir; dar</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-diadoche-bdag\" data-source=\"BDAG\" data-search=\"διαδοχή, ῆς, ἡ diadochḗ substantivo feminino sucessão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">διαδοχή, ῆς, ἡ</td><td>substantivo feminino</td><td>sucessão</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-diadochos-bdag\" data-source=\"BDAG\" data-search=\"διάδοχος, ου, ὁ diádochos substantivo masculino sucessor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">διάδοχος, ου, ὁ</td><td>substantivo masculino</td><td>sucessor</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-diazonnumi-bdag\" data-source=\"BDAG\" data-search=\"διαζώννυμι diazṓnnymi verbo atar ao redor; cingir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">διαζώννυμι</td><td>verbo</td><td>atar ao redor; cingir</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-diatheke-bdag\" data-source=\"BDAG\" data-search=\"διαθήκη, ης, ἡ diathḗkē substantivo feminino testamento; disposição; aliança; decreto; contrato BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">διαθήκη, ης, ἡ</td><td>substantivo feminino</td><td>testamento; disposição; aliança; decreto; contrato</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-diathrypto-bdag\" data-source=\"BDAG\" data-search=\"διαθρύπτω diathrýptō verbo partir; quebrar em pedaços BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">διαθρύπτω</td><td>verbo</td><td>partir; quebrar em pedaços</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-diairesis-bdag\" data-source=\"BDAG\" data-search=\"διαίρεσις, εως, ἡ diaíresis substantivo feminino divisão; distribuição; variedade; dilaceração BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">διαίρεσις, εως, ἡ</td><td>substantivo feminino</td><td>divisão; distribuição; variedade; dilaceração</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-diaireo-bdag\" data-source=\"BDAG\" data-search=\"διαιρέω diairéō verbo dividir; repartir; distribuir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">διαιρέω</td><td>verbo</td><td>dividir; repartir; distribuir</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-diaita-bdag\" data-source=\"BDAG\" data-search=\"δίαιτα, ης, ἡ díaita substantivo feminino dieta; modo de vida; habitação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">δίαιτα, ης, ἡ</td><td>substantivo feminino</td><td>dieta; modo de vida; habitação</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-diakathairo-bdag\" data-source=\"BDAG\" data-search=\"διακαθαίρω diakathaírō verbo limpar completamente; purgar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">διακαθαίρω</td><td>verbo</td><td>limpar completamente; purgar</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-diakatharizo-bdag\" data-source=\"BDAG\" data-search=\"διακαθαρίζω diakatharízō verbo limpar; purificar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">διακαθαρίζω</td><td>verbo</td><td>limpar; purificar</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-diakatelegchomai-bdag\" data-source=\"BDAG\" data-search=\"διακατελέγχομαι diakatelegchomai verbo médio refutar completamente; vencer em argumentação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">διακατελέγχομαι</td><td>verbo médio</td><td>refutar completamente; vencer em argumentação</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-diakeleuo-bdag\" data-source=\"BDAG\" data-search=\"διακελεύω diakeleúō verbo ordenar; mandar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">διακελεύω</td><td>verbo</td><td>ordenar; mandar</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-diakoneo-bdag\" data-source=\"BDAG\" data-search=\"διακονέω diakonéō verbo servir; mediar; prestar assistência; exercer um ministério BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">διακονέω</td><td>verbo</td><td>servir; mediar; prestar assistência; exercer um ministério</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-diakonia-bdag\" data-source=\"BDAG\" data-search=\"διακονία, ας, ἡ diakonía substantivo feminino mediação; serviço; ministério; auxílio; função administrativa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">διακονία, ας, ἡ</td><td>substantivo feminino</td><td>mediação; serviço; ministério; auxílio; função administrativa</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-diakonos-bdag\" data-source=\"BDAG\" data-search=\"διάκονος, ου, ὁ, ἡ diákonos substantivo masculino ou feminino intermediário; agente; auxiliar; servidor; ministro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">διάκονος, ου, ὁ, ἡ</td><td>substantivo masculino ou feminino</td><td>intermediário; agente; auxiliar; servidor; ministro</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-diakosioi-bdag\" data-source=\"BDAG\" data-search=\"διακόσιοι, αι, α diakósioi numeral adjetivo duzentos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">διακόσιοι, αι, α</td><td>numeral adjetivo</td><td>duzentos</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-diakosmeo-bdag\" data-source=\"BDAG\" data-search=\"διακοσμέω diakosméō verbo pôr em ordem; ordenar; regular BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">διακοσμέω</td><td>verbo</td><td>pôr em ordem; ordenar; regular</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-diakosmesis-bdag\" data-source=\"BDAG\" data-search=\"διακόσμησις, εως, ἡ diakósmēsis substantivo feminino regulação; disposição ordenada BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">διακόσμησις, εως, ἡ</td><td>substantivo feminino</td><td>regulação; disposição ordenada</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article id=\"entry-diadema-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διάδημα, ατος, τό</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦diádēma⟧</span><span class=\"separator\">·</span><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">(Desde Xenofonte, <i>Cyr.</i> 8, 3, 13; <i>Alex. Ep.</i> XIII, 27; XIV, 4; Epicteto 1, 24, 17; 4, 8, 30; OGI 248, 17; 383, 103; O. Bodl 262, século I a.C.; papiros; LXX; TestSol D 7:4; Test12Patr; JosAs; ApcSol.) De διαδεῖν, «atar ao redor»: «faixa, fita»; o inglês tomou por empréstimo a palavra <i>diadem</i>. Propriamente, insígnia da realeza entre os persas, faixa azul debruada de branco, colocada sobre a tiara; daí, símbolo da realeza em geral: <strong>faixa régia, diadema, coroa</strong> (Diodoro Sículo 4, 4, 4; Luciano, <i>Pisc.</i> 35, βασιλείας γνώρισμα, «insígnia da realeza»; Ezk. Trag. 71 [em Eusébio, PE 9, 29, 5]; Fílon, <i>Fuga</i> 111; Josefo, <i>Bell.</i> 1, 70; <i>Ant.</i> 12, 389; TestJud 12:4), Ap 12:3; 13:1; 19:12 (divindades com diademas: PGM 4:521, 675, 2840). Pol 1:1. Kl. Pauly I 1504s. — DELG, s.v. δέω 1; TW.</div></section></article> <article id=\"entry-diadidomi-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαδίδωμι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦diadídōmi⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">Futuro διαδώσω, LXX; primeiro aoristo διέδωκα; imperativo do segundo aoristo διάδος. Passivo: imperfeito, terceira pessoa do singular διεδίδετο; aoristo, terceira pessoa do singular διεδόθη (PsSol 1:4); particípio διαδοθείς, LXX (sobre esta forma, ver B-D-F §94, 1; W-S. §14, 11; Mlt-H. 206). <strong>Repartir entre diversas partes, distribuir, dar</strong> (assim em Tucídides e outros; Xenofonte, <i>Cyr.</i> 1, 3, 7; SIG 374, 12; POxy 1115, 6; 1194, 17; PLips 35, 10; LXX; TestJob; TestBenj 11:1). τὰ σκῦλα, «os despojos», Lc 11:22. Construção τί τινι, «algo a alguém» (Tucídides 4, 38, 4; Josefo, <i>Ant.</i> 7, 86), Lc 18:22; Ap 17:13, texto recebido (leitura erasmiana; ver aparato de Tdf.; R. Borger, TRu 52, 1987, 57). τὰ λοιπὰ τοῖς συνδούλοις, «o restante a seus conservos», Hs 5, 2, 9. Em Lc 12:42, variante textual, está implícito o destinatário de τὸ σιτομέτριον, «a porção de alimento». Com τινί, «a alguém», Jo 6:11 (variante ἔδωκεν, aparato de N²⁵; Tdf. no texto; ver R. Borger, obra citada, 34s.). Passivo em At 4:35. — M-M.</div></section></article> <article id=\"entry-diadoche-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαδοχή, ῆς, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦diadochḗ⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">(Ver διάδοχος; Ésquilo, Tucídides e outros; inscrições e papiros, com diferentes significados, especialmente relativos a pessoas; TestLevi 18:8; TestAbr A, 2, p. 78, 31 [Stone, p. 4; da passagem de Abraão desta vida para a seguinte]; Fílon, Josefo, Justino, Taciano; Atenágoras 28, 3.) <strong>Qualidade ou condição de vir depois: sucessão.</strong> ἐσχάτην εὐλογίαν, ἥτις διαδοχὴν οὐκ ἔχει, «a bênção derradeira que não tem sucessora», isto é, «a bênção insuperável», GJs 6:2. — DELG, s.v. δέχομαι, p. 268; M-M, s.v. διάδοχος.</div></section></article> <article id=\"entry-diadochos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διάδοχος, ου, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦diádochos⟧</span><span class=\"separator\">·</span><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\"><strong>Aquele que vem em seguida numa série, especialmente uma figura política: sucessor</strong> (Ésquilo e outros; Heródoto 5, 26; inscrições, papiros; Sir 46:1; 48:8; Fílon; Josefo, <i>Ant.</i> 1, 228 e outras passagens; Justino, <i>D.</i> 103, 3; 113, 3; Melitão, HE 4, 26, 7). λαμβάνειν δ., «receber como sucessor», At 24:27 (compare Josefo, <i>Ant.</i> 20, 182). — M-M; Sv.</div></section></article> <article id=\"entry-diazonnumi-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαζώννυμι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦diazṓnnymi⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">Primeiro aoristo διέζωσα, médio διεζωσάμην; particípio perfeito passivo διεζωσμένος (ver ζώννυμι; Tucídides e outros; IG II, 763b, 16 e outras inscrições; Ez 23:15, códice A; TestSol 23:3, B; Fílon, <i>Op. M.</i> 112). <strong>Atar ao redor, cingir.</strong> δ. ἑαυτόν, «atar (uma toalha) ao redor de si», Jo 13:4; ἦν διεζωσμένος, «havia atado ao redor de si», versículo 5. Médio: τὸν ἐπενδύτην, «cingir-se (isto é, vestir) a veste exterior», Jo 21:7 (Luciano, <i>Somn.</i> 6, ἐσθῆτα, «roupa»; <i>Anach.</i> 6 e outras passagens; Josefo, <i>Ant.</i> 7, 283, διεζωσμένος μάχαιραν, «cingido com uma espada»). M. Soards, JBL 102, 1983, 283s. («havia cingido sua túnica»). — DELG, s.v. ζώννυμι; M-M; TW.</div></section></article> <article id=\"entry-diatheke-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαθήκη, ης, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦diathḗkē⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">(Demócrito, Aristófanes e posteriores; inscrições, papiros, LXX, En, TestSol, TestAbr, Test12Patr; ParJer 6:21; ApcEsdr, ApcMos; AssMos, fragm. a; Fílon, Josefo, Justino; Melitão, HE 4, 26, 14.) À parte do substantivo simples θήκη, «estojo, arca», o significado desta palavra deve ser abordado a partir da forma média do verbo διατίθεμαι, frequentemente empregada no discurso jurídico e comercial para designar a disposição de bens (ver L-S-J-M, s.v. διατίθημι B), com implicação de obrigação decorrente de promessa. A disposição dos próprios bens se enquadraria naturalmente no direito testamentário; daí:<p><strong>① Última vontade, testamento.</strong> Assim, exclusivamente na época helenística (Eger [ver acepção 3, adiante], nota à p. 99; exemplos em Riggenbach 292ss.; Behm 10, 1; 2; Fílon, Josefo, Test12Patr; empréstimo lexical no uso rabínico). Hb 9:16s.; δ. κεκυρωμένη, «testamento que foi ratificado», Gl 3:15; compare o versículo 17, no qual δ. se aproxima do sentido 2 (ver κυρόω 1 e προκυρόω). Ver também E. Bammel, abaixo, e J. Swetnam, CBQ 27, 1965, 373–390. Sobre a perspectiva judaica, ver R. Katzoff, «An Interpretation of PYadin 19 — A Jewish Gift after Death», ProcXXCongPap 562–565.</p><p><strong>② Disposição, declaração de propósito, decreto; aliança.</strong> Como tradução de בְּרִית na LXX, δ. preserva o componente da disposição jurídica dos bens pessoais, mas omite a morte prevista do testador. O leitor helenístico não encontraria dificuldade, pois a imortalidade dos deuses era pressuposta. Assim, uma δ. decretada por Deus não pode depender da morte do testador para entrar em vigor. Entretanto, conserva-se outra característica essencial do testamento: é declaração da iniciativa de uma pessoa, e não resultado de um acordo entre duas partes, como um pacto ou contrato. Essa é, sem dúvida, uma das principais razões pelas quais a LXX verteu בְּרִית por δ. Nas «alianças» divinas, somente Deus estabelecia as condições; por isso, «aliança» (ver OED, s.v. <i>covenant</i>, substantivo 7) pode traduzir δ. somente se esse aspecto for mantido em vista. Na LXX, δ. adquire, portanto, um significado não seguramente atestado em fontes extrabíblicas: «decreto», «declaração de propósito», «conjunto de regulamentos» etc. Nossa literatura, fortemente influenciada pela LXX nesse campo, parece geralmente ter compreendido a palavra nesses sentidos (J. Hughes, NovT 21, 1979, 27–96 [também Hb 9:16–20; Gl 3:15–17]). Deus emitiu uma declaração de seu propósito, Rm 11:27 (Is 59:21); 1Cl 15:4 (Sl 77:37); 35:7 (Sl 49:16); Deus a mantém na lembrança (compare Sl 104:8s.; 105:45 e outras passagens), Lc 1:72; ela remonta aos tempos ancestrais, At 3:25 (PsSol 9:10; ParJer 6:21). Deus também promulgou uma ordenança (a circuncisão), At 7:8 (compare Gn 17:10ss.). Como a santa vontade de Deus foi estabelecida em diversas ocasiões (Gn 6:18; 9:9ss.; 15:18; 17:2ss.; Êx 19:5 e frequentemente), é possível falar em διαθῆκαι, «decretos, garantias» (compare διαθῆκαι πατέρων, «alianças dos pais», Sb 18:22; 2Mac 8:15. Contudo, o plural também é empregado para um único testamento: Diógenes Laércio 4, 44; 5, 16. Em citações ou referências a Teofrasto, ora se usa o singular [Diógenes Laércio 5, 52; 56], ora o plural [5, 51; 57]), Rm 9:4; Ef 2:12.</p><p>Especial ênfase recai sobre a δ. καινή, «nova aliança», já mencionada em Jr 38:31, que Deus planejou estabelecer futuramente (Hb 8:8–10; 10:16). O decreto ou aliança de Deus dirigido aos cristãos é καινὴ δ. (δ. δευτέρα, «segunda aliança», Orígenes, <i>C. Cels.</i> 2, 75), Lc 22:20; 1Co 11:25; 2Co 3:6; Hb 8:8; 9:15a; PtK 2, p. 15, 5, ou δ. νέα, Hb 12:24; PtK 2, p. 15, 6; como δ. αἰώνιος, «aliança eterna» (compare Jr 39:40; En 99:2), Hb 13:20, ela supera amplamente (Hb 7:22; 8:6) a παλαιὰ δ., «antiga aliança», 2Co 3:14, ou πρώτη δ., «primeira aliança», Hb 9:15b, com a qual é contrastada. Ambas são mencionadas (Did., <i>Gen.</i> 46, 4; 235, 26), Gl 4:24; B 4:6ss. (Êx 34:28; 31:18; Justino, <i>D.</i> 67, 9). Houve derramamento de sangue quando a antiga aliança foi proclamada no Sinai, Hb 9:20 (Êx 24:8); o mesmo se dá com a nova aliança, Hb 10:29. τὸ αἷμά μου τ. διαθήκης, «meu sangue da aliança», Mt 26:28; Mc 14:24 (E. Lohse, <i>Märtyrer u. Gottesknecht</i>², 1963, 122–129), deve provavelmente ser entendido em relação a esse sangue (ver W. Wrede, ZNW 1, 1900, 69–74; T. Robinson, «My Blood of the Covenant», <i>KMarti Festschr.</i> 1925, 232–237; crítica dessa posição em G. Walther, <i>Jesus, D. Passalamm des Neuen Bundes</i>, 1950, 22–27, e J. Jeremias, TLZ 1951, 547; sobre o contexto siríaco, J. Emerton, JTS 13, 1962, 111–117; também É. Delebrecque, <i>Études grecques sur l’vangile de Luc</i>, 1976, 109–121). A variante textual de Lc 22:29 pode derivar de Jr 39:40 ou Is 55:3 LXX (sobre o acusativo cognato, ver Aristófanes, <i>Aves</i> 440). δ. também pode ser traduzida por «decreto» na Epístola de Barnabé (4:6ss.; 6:19; 9:6; 13:1, 6; 14:1ss., δ. δοῦναί τινι, «dar uma δ. a alguém»); mas a ocorrência frequente da ideia de herança (6:19; 13:1, 6; 14:4s.) torna provável que esse «decreto» deva ser entendido como parte de um testamento.</p><p><strong>③ Pacto, contrato.</strong> Esse significado parece firmemente estabelecido na época greco-romana (F. Norton, <i>A Lexicographical and Historical Study of Διαθήκη</i>, Chicago, 1908, 31ss.; E. Bruck, <i>D. Schenkung auf d. Todesfall im griech. u. röm. Recht</i> I, 1909, 115ss.; J. Wackernagel, <i>D. Kultur d. Gegenw.</i> I 82, 1907, 309). Permanece duvidoso se esse significado influenciou nossa literatura em alguns lugares (exceção bastante provável: Lc 22:29, variante textual, com seu teor administrativo; a expressão διατίθεμαι δ., como Aristófanes, <i>Av.</i> 440, referente à celebração de um tratado). Porém, o uso da palavra nesse sentido constituiria novamente uma ponte para o emprego na LXX. A expressão ἡ κιβωτὸς τ. διαθήκης, «arca da aliança», isto é, caixa sagrada (inglês <i>ark</i>, empréstimo do latim <i>arca</i>) que simbolizava a promessa da presença de Deus com Israel (Êx 31:7; 39:14 e outras passagens), Hb 9:4; Ap 11:19, ou αἱ πλάκες τ. διαθ., «tábuas da aliança» (Êx 34:28; Dt 9:9, 11), Hb 9:4, teriam exigido dos leitores antigos certo conhecimento da tradição israelita.</p><p>Bibliografia: E. Riggenbach, <i>D. Begriff d. Διαθήκη im Hb</i>, em <i>Theol. Stud. f. TZahn</i>, 1908, 289ss.; <i>Hb</i>², 1922, 205ss. e outras passagens; A. Carr, «Covenant or Testament?», <i>Exp.</i> 7ª série, 7, 1909, 347ss.; J. Behm, <i>D. Begriff D. im NT</i>, 1912; E. Lohmeyer, <i>Diatheke</i>, 1913; W. Ferguson, <i>Legal Terms Common to the Macedonian Inscr. and the NT</i>, 1913, 42–46 (documentos testamentários); H. Kennedy, <i>Exp.</i> 8ª série, 10, 1915, 385ss.; G. Vos, «Hebrews, the Epistle of the Diatheke», PTR 13, 1915, 587–632; 14, 1916, 1–61; O. Eger, ZNW 18, 1918, 84–108; E. Burton, ICC Gal, 1921, 496–505; L. da Fonseca, «Διαθήκη foedus an testamentum?», <i>Biblica</i> 8, 1927; 9, 1928; E. Bammel, «Gottes διαθήκη (Gal 3:15–17) u. d. jüd. Rechtsdenken», NTS 6, 1960, 313–319; N. Dow, <i>A Select Bibliography on the Concept of Covenant</i>, <i>Austin Seminary Bulletin</i> 78, 6, 1963; C. Roetzel, <i>Biblica</i> 51, 1970, 377–390 (Rm 9:4); D. McCarthy, <i>Berit and Covenant (Deut.)</i>, 1972, 65–85; E. Christiansen, <i>The Covenant in Judaism and Paul</i>, 1995. — DELG, s.v. θήκη; M-M; TW; Sv.</p></div></section></article> <article id=\"entry-diathrypto-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαθρύπτω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦diathrýptō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">Futuro διαθήσομαι; segundo aoristo passivo διεθρύβην, LXX; construção τινί τι (ver θρύπτω; Homero e outros). <strong>Quebrar algo em pedaços, partir</strong>; τινί τι, «partir pão para os famintos», B 3:3 (Is 58:7). — DELG, s.v. θρύπτω.</div></section></article> <article id=\"entry-diairesis-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαίρεσις, εως, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦diaíresis⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">(Ver διαιρέω.) Em geral, condição ou circunstância de estar dividido. <strong>① Divisão ou distribuição de alguma coisa entre pessoas; repartição, divisão</strong> (Heródoto e outros; inscrições, papiros; Jt 9:4; Sir 14:15; Fílon). διαιρέσεις χαρισμάτων, «distribuições de dons espirituais», 1Co 12:4; compare os versículos 5 e 6 (esta interpretação tem apoio no versículo 11: διαιροῦν ἑκάστῳ καθὼς βούλεται, «distribuindo a cada um conforme quer»). Outra interpretação defensável para essa passagem é <strong>② Estado de diferença na natureza dos objetos ou acontecimentos; diferença, variedade</strong> (Platão, <i>Soph.</i> 267b: τίνα μείζω διαίρεσιν ἀγνωσίας τε καὶ γνώσεως θήσομεν, «que distinção maior entre ignorância e conhecimento estabeleceremos?»; Luciano, <i>Hermot.</i> 52; Epicteto 2, 6, 24; Taciano 12, 1; Atenágoras 10, 3; 12, 2; R. 71, 16). <strong>③ Divisão por ação violenta; dilaceração</strong> (quanto a conflitos políticos, TestJud 22:1, διαιρέσεις κατ’ ἀλλήλων, «divisões uns contra os outros»), do corpo em determinadas formas de tortura e execução, IRo 5:3 (texto incerto; ver ἀνατομή; compare Artemidoro 1, 67, p. 62, 7, διαιρέσεις ὑπὸ σιδήρου, «cortes por instrumento de ferro»; Fílon, <i>Agr.</i> 129, ἄνευ τομῆς κ. διαιρέσεως, «sem corte nem divisão»). — DELG, s.v. αἱρέω; M-M; TW; Sv.</div></section></article> <article id=\"entry-diaireo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαιρέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦diairéō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">Ver διαίρεσις; futuro διελῶ, LXX; segundo aoristo διεῖλον, subjuntivo διέλω. Passivo: futuro, terceira pessoa do singular διαιρεθήσεται, LXX; aoristo διῃρέθην, LXX; perfeito διῄρημαι, LXX (Homero e outros; inscrições, papiros, LXX). <strong>Distribuir, dividir</strong> (Josefo, <i>Ant.</i> 5, 88, com τι). Construção τινί τι, «algo a alguém» (Xenofonte, <i>Cyr.</i> 4, 5, 51; <i>Hell.</i> 3, 2, 10; frequentemente em papiros, por exemplo PLond III, 880, 11 [113 a.C.], p. 9, διειρῆσθαι τὰ ὑπάρχοντα αὐτῷ ἔγγαια τοῖς ἑαυτοῦ υἱοῖς, «ter distribuído seus bens fundiários a seus próprios filhos»; Js 18:5; Jt 16:24; 1Mac 1:6). διεῖλεν αὐτοῖς τὸν βίον, «dividiu seus bens entre eles», Lc 15:12. «Repartir algo a alguém» (Michel 1001 VI, 18, ὁ ἀρτυτὴρ [«o oficiante»] διελεῖ τὰ ἱερὰ τοῖς παροῦσι, «o oficiante distribuirá as porções sagradas aos presentes»), 1Co 12:11. Uso absoluto: ἐὰν ὀρθῶς μὴ διέλῃς, «se não dividiste corretamente (o sacrifício)», 1Cl 4:4 (Gn 4:7). — DELG, s.v. αἱρέω; M-M; TW.</div></section></article> <article id=\"entry-diaita-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίαιτα, ης, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦díaita⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">(Compare διαιτάομαι, «levar a própria vida, viver»; Píndaro, Heródoto e outros; LXX; TestSol 11:2 P; TestJos 3:5 [variante τροφήν]; Josefo, <i>Bell.</i> 2, 151; <i>C. Ap.</i> 2, 240.) Originalmente, «modo de vida». <strong>① Alimentação, dieta</strong>, Dg 5:4. <strong>② Habitação, lugar de morada</strong> (Diodoro Sículo 3, 30, 2; Pseudo-Aristóteles, <i>De Mundo</i> 6, 398b, 32; Plutarco, <i>Mor.</i> 515e; OGI 383, 27 [século I a.C.]; Josefo, <i>Ant.</i> 15, 331; Taciano 9, 1, τῆς ἐν οὐρανῷ διαίτης, «a vida no céu»; também como empréstimo em escritos rabínicos), 1Cl 39:8 (Jó 5:3). δ. τῆς σκηνῆς σου οὐ μὴ ἁμάρτῃ, «a morada da tua tenda não sofrerá falta», 1Cl 56:13 (Jó 5:24). — DELG.</div></section></article> <article id=\"entry-diakathairo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακαθαίρω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦diakathaírō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">Infinitivo do primeiro aoristo διακαθᾶραι (ver καθαρίζω; Aristófanes, Platão e outros; BCH 27, 1903, 73, linha 79). <strong>Livrar completamente de algo indesejável; purgar inteiramente, limpar</strong> algo (τι), a eira, Lc 3:17 (Alcífron 2, 23, 1, ἄρτι μοι τὴν ἅλω διακαθήραντι, «tendo eu acabado de limpar a eira»). — M-M.</div></section></article> <article id=\"entry-diakatharizo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακαθαρίζω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦diakatharízō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">Futuro διακαθαριῶ (não encontrado em outros lugares; ver o verbete precedente). <strong>Limpar</strong> algo (τι), Mt 3:12; Lc 3:17, variante textual. — DELG, s.v. καθαρός.</div></section></article> <article id=\"entry-diakatelegchomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακατελέγχομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦diakatelegchomai⟧</span><span class=\"separator\">·</span><span>verbo médio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">Imperfeito διακατηλεγχόμην (ver ἐλέγχω; não encontrado em outros lugares). <strong>Refutar, derrotar pela argumentação</strong>, com dativo (τινί): τοῖς Ἰουδαίοις, «aos judeus», At 18:28. — TW.</div></section></article> <article id=\"entry-diakeleuo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακελεύω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦diakeleúō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">(Ver κελεύω; voz média desde Heródoto; a ativa somente em Filóstrato, <i>Vi. Apollon.</i> 1, 31, variante textual; POxy 2340, 11 [192 d.C.]; e na Suda.) <strong>Ordenar, mandar</strong>, com dativo de pessoa (τινί) seguido de infinitivo, Jo 8:5, variante textual.</div></section></article> <article id=\"entry-diakoneo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακονέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦diakonéō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">(Ver os dois verbetes seguintes.) Imperfeito διηκόνουν; futuro διακονήσω; primeiro aoristo διηκόνησα; infinitivo perfeito δεδιηκονηκέναι (AssMos, fragm. k, Denis, p. 67); aoristo passivo διηκονήθην; sobre o aumento, ver B-D-F §69, 4; W-S. §12, 6; Mlt-H. 192 (Sófocles, Heródoto e outros; raro em inscrições e papiros; nunca na LXX, mas presente em Fílon e Josefo). Em geral, <strong>prestar serviço de várias maneiras</strong>, por determinação de alguém ou voluntariamente, frequentemente com a sugestão de deslocamento.<p><strong>① Atuar como intermediário; agir como mediador, agente; estar ao serviço de alguém</strong>, com função intermediária expressa ou implícita (tabuinha de chumbo Sb 4947, 2, διακόνησόν μοι, «serve-me de intermediário»; no pedido de um amante, «serve de intermediário [médium] para mim», PWarr 21, 4; 8; Luciano, <i>Cont.</i> 1, sobre Hermes como mensageiro de Zeus; Teofrasto, <i>Char.</i> 2, 9, ir buscar coisas; Justino, <i>D.</i> 79, 2; compare o papel do Arrependimento em JosAs 15:7). Com dativo de pessoa e acusativo da coisa: οὐχ ἑαυτοῖς ὑμῖν δὲ διηκόνουν αὐτά, «não atuavam como agentes em favor de si mesmos, mas em favor de vós nessas coisas», 1Pe 1:12 (para serviço que consiste na transmissão de uma mensagem, compare Josefo, <i>Ant.</i> 6, 298). Para contraste semelhante, com indicação da missão de um intermediário: οὐκ ἦλθεν διακονηθῆναι ἀλλὰ διακονῆσαι, «não veio para ser servido, mas para servir», Mt 20:28; Mc 10:45 (isto é, o Homem [Filho do Homem] veio cumprir uma incumbência em benefício de outros, não de si próprio [dando a vida como resgate]; compare Mt 4:11; paralelo Mc 1:13 [serviço prestado por mensageiros divinos]). Sobre Jesus no desempenho de sua missão: [ἀ]νῆλθε[ν δια]κονῶν, AcPl BMM, verso, linhas 13s. Fm 13 sugere que Onésimo pode ser utilizado por Paulo numa incumbência em favor do evangelho. πορεύομαι … διακονῶν τοῖς ἁγίοις, «vou numa missão em favor do povo de Deus» (REB), Rm 15:25 (ver 3). Sobre a entrega de um objeto: χάρις διακονουμένη ὑφ’ ἡμῶν, «dádiva que estamos transmitindo» (referência à coleta cuja entrega assumiram como responsabilidade), 2Co 8:19; compare o versículo 20. Em linguagem figurada: ἐπιστολὴ Χριστοῦ διακονηθεῖσα ὑφ’ ἡμῶν, «carta de Cristo entregue por nós», 2Co 3:3 (W. Baird, «Letters of Recommendation», JBL 80, 1961, 190).</p><p><strong>② Cumprir obrigações</strong>, sem destaque para a função intermediária. <strong>ⓐ Em serviços não especificados: cumprir deveres, prestar auxílio, servir</strong> alguém, com dativo (τινί) (Demóstenes 9, 43; UPZ 18, 23 [163 a.C.]; δαίμοσι δ., «servir aos demônios», Orígenes, <i>C. Cels.</i> 2, 51, 38), Mt 8:15; Mc 1:31; Lc 4:39; GJs 6:3; διακονοῦσαι αὐτῷ, «prestando-lhe serviço», Mt 27:55; compare Mc 15:41. διακόνει μοι, «serve-me», Hs 8, 4, 1; compare 2; Jo 12:26; At 19:22. Também εἰς ἑαυτοὺς αὐτὸ δ., «servir uns aos outros com isso», 1Pe 4:10. Com acusativo de coisa: ὅσα διηκόνησεν, «quantos serviços prestou», 2Tm 1:18; compare Hs 2:10. Emprego absoluto (POxy 275, 10 [século I d.C.]), 1Pe 4:11. Passivo (Josefo, <i>Ant.</i> 10, 242); ἁπλῶς δ., «cumprir um serviço com singeleza de coração», Hm 2:6. <strong>ⓑ Servir alguém à mesa, atender durante uma refeição</strong> (com dativo, τινί) (Menandro, <i>Fgm.</i> 272; Pírgion [época helenística], 467, fragm. 1 Jac. [refeição comunitária em Creta]; Diodoro Sículo 4, 36, 2; 5, 28, 4; Fílon, <i>Vi. Cont.</i> 70; TestJob 12:1 e outras passagens; Josefo, <i>Ant.</i> 11, 163; 166), Lc 12:37; 17:8. Emprego absoluto, Lc 10:40; Jo 12:2; GJs 6:3. Em sentido figurado: ὡς ὁ διακονῶν, «como aquele que serve à mesa», Lc 22:26s.</p><p><strong>③ Atender a uma necessidade imediata, ajudar</strong>, com dativo (Irineu 1, pref. 3 [Harvey I 7, 1]): πότε οὐ διηκονήσαμέν σοι;, «quando deixamos de te ajudar?», Mt 25:44 (mas ver 4 e Collins); ἐκ τῶν ὑπαρχόντων, «ajudavam a sustentá-los com seus recursos», Lc 8:3 (K. Torjesen, <i>When Women Were Priests</i>, 1993, 53ss.); os santos, Rm 15:25 (J. O’Rourke, CBQ 29, 1967, 116–118; mas ver 1); Hb 6:10.</p><p><strong>④ Exercer funções oficiais, ministrar</strong>, em contexto cúltico (do serviço sagrado junto ao altar, Josefo, <i>Ant.</i> 3, 155; compare PGM 36, 304 e 335, παρὰ θεοῖς δ., «servir junto aos deuses»); sobre os διάκονοι, 1Tm 3:10; καλῶς δ., «ministrar bem», versículo 13; ἀγνῶς καὶ σεμνῶς, «com pureza e dignidade», Hv 3, 5, 1; em oposição a κακῶς, «mal», Hs 9, 26, 2. Collins (ver abaixo), p. 65, argumenta que Mt 25:44 pertence a esta classificação: os condenados alegam ter demonstrado dedicação completa aos interesses do Senhor.</p><p><strong>⑤ At 6:2 apresenta problema especial: cuidar, encarregar-se</strong>, com dativo de coisa; τραπέζαις, «cuidar das mesas», pode ser entendido como servir alimentos às mesas (compare βούλομαι … διακονῆσαι τοῖς πτωχοῖς σήμερον ἐν τῇ σῇ τραπέζῃ, «quero hoje servir os pobres à tua mesa», TestJob 12:1); porém, é improvável que algumas viúvas fossem privadas de comida numa refeição comunitária. O termo διακονία, versículo 1, refere-se mais provavelmente à responsabilidade administrativa (ver διακονία 5), um de cujos aspectos é o cuidado das viúvas, sem especificar qual assistência lhes era destinada. O versículo 2 pode conter um jogo de palavras com τὸν λόγον τοῦ θεοῦ, «a palavra de Deus», sendo λόγος a designação de um lançamento em livro contábil; nesse caso, τράπεζα, também termo bancário (ver L-S-J-M, s.v. II), pode aqui designar contas (ver τράπεζα 1c).</p><p>Bibliografia: W. Brandt, <i>Dienst u. Dienen im NT</i>, 1931; E. Schweizer, <i>D. Leben des Herrn in d. Gemeinde u. ihren Diensten</i>, 1946; P. Boulton, «Διακονέω and Its Cognates in the 4 Gospels», TU 73, 1959, 415–422; J. Collins, <i>Diakonia</i>, 1990. — DELG, s.v. διάκονος; M-M; TW.</p></div></section></article> <article id=\"entry-diakonia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακονία, ας, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦diakonía⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">(Ver διακονέω, διάκονος; Tucídides e outros; IG XII/5, 600, 14 [século III a.C.]; PFouad 25, verso I, 1 [século II d.C.]; 1Mac 11:58; Est 6:3, 5 [ambas variantes textuais]; TestJob 11:1ss.; 15:1; Josefo.) <strong>① Serviço prestado na capacidade de intermediário: mediação, incumbência.</strong> δ. τῆς λειτουργίας, «mediação desta obrigação pública», 2Co 9:12; compare o versículo 13. ἡ δ. ἡ εἰς Ἰερουσαλήμ, «minha missão em favor de Jerusalém» (= meu papel como agente da entrega [da dádiva] a Jerusalém; a variante δωροφορία, «entrega de presentes», indica que δ. denota função intermediária; o contexto informa o leitor de que a missão compreende o transporte de uma dádiva), Rm 15:31; compare 2Co 8:4; 9:1. Sobre a «coleta»: E. Lombard, RTP 35, 1902, 113–139; 262–281; M. Goguel, RHPR 4, 1925, 301–318; K. Nickle, <i>The Collection</i>, 1966. πνεύματα εἰς δ. ἀποστελλόμενα, «espíritos enviados para uma incumbência», Hb 1:14.<p><strong>② Desempenho de um serviço.</strong> <strong>ⓐ Em geral, serviço:</strong> πρὸς τὸν καταρτισμὸν τ. ἁγίων εἰς ἔργον διακονίας, «para preparar o povo de Deus para um serviço produtivo», Ef 4:12 (esta tradução, como nas edições posteriores da RSV e também na NRSV e REB, pressupõe que não se coloque vírgula antes de εἰς, como na KJV, RV, RSV¹, JB e outras; interpretação diferente na acepção 3). δ. τοῦ λόγου, «serviço da palavra», At 6:4; ἡ ὑμῶν δ., «serviço prestado a vós», 2Co 11:8. Também 1Co 16:15; 2Tm 4:11; Ap 2:19. <strong>ⓑ Empenho específico nos preparativos de um acontecimento social, como uma refeição</strong> (ver Plutarco, <i>Philopoem.</i> 357 [2, 3]: uma anfitriã megarense confunde o estadista Filopêmen com um de seus auxiliares e o manda cortar lenha como parte da διακονία, isto é, dos preparativos de uma refeição; Josefo, <i>Ant.</i> 2, 65; 11, 163, διακονεῖν τινι τὴν ἐπὶ τοῦ πότου διακονίαν, «prestar a alguém o serviço relacionado à bebida»). περιεσπᾶτο περὶ πολλὴν δ., «(Marta) estava distraída com muitos preparativos», Lc 10:40.</p><p><strong>③ Atuação no interesse de um público mais amplo: serviço, ofício</strong>, dos profetas e apóstolos, 1Tm 1:12; κλῆρος τῆς δ., «parte neste ministério», At 1:17; τόπος τῆς δ., «lugar neste ministério», versículo 25. Do serviço dos levitas, 1Cl 40:5; do ofício de um supervisor eclesiástico, IPhld 1:1; 10:2; ISm 12:1; Hs 9, 27, 2. δ. λαμβάνειν, «receber um ministério», At 20:24. διαιρέσεις διακονιῶν, «diversidades de ministérios», 1Co 12:5. δ. τοῦ θανάτου, «ministério da morte», sobre a lei do Antigo Testamento, 2Co 3:7; também δ. τῆς κατακρίσεως, «ministério da condenação», versículo 9, em oposição a δ. τῆς δικαιοσύνης, «ministério da justiça», no mesmo lugar; δ. τοῦ πνεύματος, «ministério do Espírito», versículo 8, quanto ao serviço em favor do evangelho; compare At 21:19; Rm 11:13; 2Co 4:1; 6:3; Cl 4:17; 2Tm 4:5. δ. τῆς καταλλαγῆς, «ministério da reconciliação», 2Co 5:18. τὴν δ. τελέσαι, «cumprir esta incumbência», Hm 2:6; sobre obediência e exortação, 12, 3, 3; Hs 1:9; 2:7. τελειῶσαι … τὴν δ., «cumprir … minha responsabilidade», At 20:34. Ef 4:12 pertence aqui se, com KJV, RV, RSV¹ e outras, e em oposição a N. e outras edições, for colocada vírgula antes de εἰς (ver Collins [citado ao fim da acepção 5], 233s.).</p><p><strong>④ Prestação de assistência específica: auxílio, apoio</strong> (Arriano, <i>Peripl.</i> 3, 1, εἰς διακονίαν, «para apoio»), especialmente esmolas e doações de caridade (AcThom 59 [Aa II/2, 176, 2], χρήματα πολλὰ εἰς διακονίαν τῶν χηρῶν, «muito dinheiro para cuidar das viúvas»), At 6:1. εἰς δ. πέμψαι τί τινι, «enviar alguma coisa a alguém como ajuda», At 11:29; compare 12:25.</p><p><strong>⑤ Função administrativa: serviço como atendente, auxiliar ou assistente</strong> (o inglês tomou emprestada a palavra <i>deacon</i>; Hipólito, <i>Ref.</i> 7, 36, 3), Rm 12:7 (Ltzm., ZWT 55, 1913, 110); IMg 6:1; IPhld 10:2; Hs 9, 26, 2. — P. Abbing, <i>Diakonia</i>, diss. Utrecht, 1950; B. Reicke, <i>Diakonie, Festfreude u. Zelos usw.</i>, 1951, 19–164; RAC III 909–917; W. Brandt, <i>Dienst u. Duienen im NT</i>, 1931 (diss. Münster: <i>Diakonie u. das NT</i>, 1923); J. Collins, <i>Diakonia</i>, 1990. — DELG, s.v. διάκονος; M-M; TW; Sv.</p></div></section></article> <article id=\"entry-diakonos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διάκονος, ου, ὁ, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦diákonos⟧</span><span class=\"separator\">·</span><span>substantivo masculino ou feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">(Ver διακονέω, διακονία; tragediógrafos, Heródoto e outros; inscrições, papiros, LXX; TestSol 6:10 L, em lugar de δράκοντας; TestJud 14:2; Fílon, Josefo, Justino, Taciano, Irineu, Hipólito.) Em geral, <strong>alguém que se ocupa de alguma coisa de maneira útil a outra pessoa</strong>.<p><strong>① Aquele que serve como intermediário numa transação: agente, intermediário, mensageiro</strong> (compare Josefo, <i>Ant.</i> 1, 298, sobre Raquel que conduziu Jacó a Labão; ver também <i>Ant.</i> 7, 201; 224 e outras passagens; em <i>Ant.</i> 8, 354, Eliseu é Ἠλίου καὶ μαθητὴς καὶ δ., «discípulo e servidor de Elias»; Epígono é δ. καὶ μαθητής, «servidor e discípulo», de Noeto, em Hipólito, <i>Ref.</i> 9, 7, 1). Dos intermediários de uma divindade: em geral θεοῦ δ., «agente de Deus» (Epicteto 3, 24, 65, Diógenes como τοῦ Διὸς διάκονος, «agente de Zeus»; Aquiles Tácio 3, 18, 5, δ. θεῶν, «agente dos deuses»; compare Fílon, <i>De Jos.</i> 241; Josefo, <i>Bell.</i> 3, 354), 2Co 6:4; 1Ts 3:2 (compare 1Co 3:5), ver abaixo; Tt 1:9b, variante textual; Hs 9, 15, 4. δ. Χριστοῦ, «agente de Cristo», 2Co 11:23; Cl 1:7; 1Tm 4:6 (compare Taciano 13, 3, δ. τοῦ πεπονθότος θεοῦ, «agente do Deus que sofreu»). Dos oficiais considerados coletivamente como sistema político: o agente ἡ ἐξουσία, «as autoridades (governamentais)», como θεοῦ δ., «servidor de Deus», Rm 13:4; aqui, o vocábulo é compreendido como substantivo feminino (Heraclit. Sto. 28, p. 43, 15; para abstrações, Epicteto 2, 23, 8; 3, 7, 28).</p><p>Com referência específica a um aspecto da mensagem divina, sobre os apóstolos e outros cristãos destacados incumbidos de sua transmissão (δ. τῆς διδασκαλίας, «agente da doutrina», Orígenes, <i>C. Cels.</i> 1, 62, 30), Cl 1:23; Ef 3:7; δ. καινῆς διαθήκης, «agente de uma nova aliança», 2Co 3:6; δ. δικαιοσύνης, «agente da justiça» (em oposição a δ. τοῦ σατανᾶ, «agente de Satanás»), 2Co 11:15. δ. τοῦ θεοῦ ἐν τ. εὐαγγελίῳ, «agente de Deus no interesse do evangelho», 1Ts 3:2, variante textual (em lugar de συνεργός, «cooperador»); compare δ. χριστοῦ Ἰησοῦ, «agente de Cristo Jesus» (se Timóteo transmitir ensinamentos corretos, será considerado excelente transmissor da tradição evangélica), 1Tm 4:6; δ. ἐν κυρίῳ, «agente no Senhor», Ef 6:21; Cl 1:25, indiretamente como δ. ἐκκλησίας, «agente da igreja»; de Cristo como agente de Deus: δ. περιτομῆς, «agente da circuncisão», em favor dos circuncidados, isto é, dos descendentes de Abraão, Rm 15:8. Compare Febe, Rm 16:1 e variante textual na subscrição; de Tíquico como mensageiro fiel, Cl 4:7 (Platão, <i>Rep.</i> 370e, «intermediário, mensageiro»; sobre Hermes, ver G. Elderkin, «Two Curse Inscriptions», <i>Hesperia</i> 6, 1937, 389, tábua 3, linha 8; Josefo, <i>Ant.</i> 7, 201; 224 e outras passagens).</p><p><strong>② Aquele que realiza algo por ordem de um superior: auxiliar de alguém.</strong> O contexto determina se o termo, com ou sem artigo ὁ, οἱ, inclui mulheres ou se se refere exclusivamente a homens. Mt 20:26; 23:11; Mc 10:43; a todos, 9:35; Pol 5:2. Dos atendentes de mesa (Xenofonte, <i>Mem.</i> 1, 5, 2; Políbio 31, 4, 5; Luciano, <i>Merc. Cond.</i> 26; Ateneu 7, 291a; 10, 420e; Josefo, <i>Ant.</i> 6, 52), Jo 2:5, 9. Dos integrantes do séquito real, Mt 22:13. — Dos seguidores de Jesus, em geral, aqueles que estão a seu serviço, Jo 12:26. Em sentido satírico, ἁμαρτίας δ., «agente do pecado», Gl 2:17 (compare as construções genitivas da acepção 1; compare Taciano 19, 2, acerca da adivinhação como instrumento ou meio de desejos desmedidos: πλεονεξιῶν … δ.).</p><p><strong>Auxiliar que presta serviço em contexto cúltico: atendente, assistente.</strong> (Heródoto 4, 71, 4, «auxiliar, integrante de séquito»; Pausânias 9, 82, 2, «atendentes».) Os derivados ingleses <i>deacon</i> e <i>deaconess</i> são termos técnicos cujos significados variam na história eclesiástica e por isso são inadequados para verter o uso neotestamentário de δ. Quando alguém é designado para serviço ministerial especial numa comunidade cristã (ver Justino, <i>A I</i> 65, 5; 67, 5; Irineu 1, 13, 5 [Harvey I 121, 6]; Hipólito, <i>Ref.</i> 9, 12, 22), especialmente homens (para δ. como titular de ofício religioso fora do cristianismo, IMagnMai 109 [cerca de 100 a.C.]; IG IV, 474, 12; 824, 6; IX, 486, 18; CIG II, 1800, 1; 3037, 4; II, adendos 1793b, 18, p. 982; Thieme 17s.; MAI 27, 1902, p. 333s., n.º 8, 22), Fp 1:1 (E. Best, «Bishops and Deacons», TU 102, 1968, 371–376); 1Tm 3:8, 12; 4:6; Tt 1:9a, variante textual; Fm, variante textual na subscrição; 1Cl 42:4s. (Is 60:17); Hv 3, 5, 1; Hs 9, 26, 2; IEph 2:1; IMg 2; 6:1; 13:1; ITr 2:3; 3:1; 7:2; IPhld, inscrição; 4; 7:1; 10:1s.; 11:1; ISm 8:1; 10:1; 12:2; IPol 6:1; Pol 5:3; D 15:1.</p><p>Bibliografia: Harnack, <i>D. Lehre d. Zwölf Apostel</i>, TU II 1; 2, 1884, 140ss.; <i>Entstehung u. Entwicklung d. Kirchenverfassung</i>, 1910, 40ss.; F. Hort, <i>The Christian Ecclesia</i>, 1898, 202–208; Ltzm., ZWT 55, 1913, 106–113 = <i>Kleine Schriften</i> I, 1958, 148–153; H. Lauerer, «D. 'Diakonie' im NT», NKZ 42, 1931, 315–326; W. Brandt, <i>Dienst u. Duienen im NT</i>, 1931 (diss. Münster: <i>Diakonie u. das NT</i>, 1923); RAC III 888–899; J. Collins, <i>Diakonia</i>, 1990 (p. 254: «Cuidado, solicitude e amor — esses componentes de significado, introduzidos na interpretação desta palavra e seus cognatos por Wilhelm Brandt — simplesmente não integram seu campo semântico»). Bibliografia adicional nos verbetes ἐπίσκοπος e πρεσβύτερος.</p><p>Como as responsabilidades de Febe enquanto διάκονος, Rm 16:1 e variante na subscrição, parecem ir além das dos atendentes cúlticos, homens ou mulheres (quanto a mulheres em funções cúlticas: <i>ministra</i>, ver Plínio, <i>Ep.</i> 10, 96, 8; compare CIG II 3037, διάκονος Τύχη, «Tique, diácono»; ἡ δ., Marco Diácono, <i>Vi. Porphyr.</i>, p. 81, 6; MAI [ver acima] 14, 1889, p. 210; Pel.-Leg. 11, 18; numerosas referências documentais em <i>New Docs</i> 4, 239s.), as referências em Romanos classificam-se melhor na acepção 1, acima (mas ver D. Archea, <i>Bible Translator</i> 39, 1988, 401–409). Para a ideia de serviço das mulheres, compare Hv 2, 4, 3; assim, Hs 9, 26, 2 pode incluir mulheres. Bibliografia adicional no verbete χήρα b. — Thieme 17s.; B. 1334; DELG; M-M; TW; Sv.</p></div></section></article> <article id=\"entry-diakosioi-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακόσιοι, αι, α</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦diakósioi⟧</span><span class=\"separator\">·</span><span>numeral adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">(Homero e posteriores; papiros, LXX; TestSol, Test12Patr; Josefo, <i>Vi.</i> 90; 115; Taciano 31, 3.) <strong>Duzentos</strong>, Mc 6:37; Jo 6:7; 21:8; At 23:23; 27:37 (sobre o número de pessoas, ver Hemer, <i>Acts</i> 149; compare episódio semelhante envolvendo cerca de seiscentas pessoas, Josefo, <i>Vi.</i> 15); Ap 11:3; 12:6. — Mussies 220s.; DELG.</div></section></article> <article id=\"entry-diakosmeo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακοσμέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦diakosméō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">Aoristo passivo διεκοσμήθην, LXX; perfeito passivo, terceira pessoa do singular διακεκόσμηται (Atenágoras 10:1); particípio διακεκοσμημένος, 2Mac 3:25 (ver διακόσμησις, κοσμέω; Homero e outros). <strong>Fazer uma disposição ordenada; pôr em ordem, regular</strong> algo (τί) (Josefo, <i>Ant.</i> 6, 31), os céus (Fílon, <i>Op. M.</i> 53), 1Cl 33:3 (como expressão cosmológica desde os antigos filósofos jônios da natureza e, depois, especialmente em escritores estoicos; ver Knopf, <i>Hdb.</i>, ad loc.). — DELG, s.v. κόσμος.</div></section></article> <article id=\"entry-diakosmesis-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακόσμησις, εως, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦diakósmēsis⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">(Ver διακοσμέω; Platão e posteriores; termo estoico; Sb 8858, 46 [século III a.C.]; 2Mac 2:29; Sl 32:6, Símaco; Ct 7:5, Símaco; Fílon; Josefo, <i>Ant.</i> 1, 69; Ar. 1:1; Taciano.) <strong>Regulação, disposição ordenada</strong>, Pápias (4). — DELG, s.v. κόσμος.</div></section></article>"};
